    fn complete_one_deck_position() -> (PlayPhase, Vec<PlayerID>) {
        let ids: Vec<PlayerID> = (0..4).map(PlayerID).collect();
        let mut propagated = PropagatedState::default();
        propagated.players = ids
            .iter()
            .map(|id| Player::new(*id, format!("p{}", id.0)))
            .collect();
        propagated.num_decks = Some(1);
        let deck = Deck::default();
        let configured = deck.cards().collect::<Vec<_>>();
        let kitty = configured[..2].to_vec();
        let trump = Trump::NoTrump { number: None };
        let mut hands = Hands::new(ids.iter().copied());
        hands.set_trump(trump);
        for (index, cards) in configured[2..].chunks_exact(13).enumerate() {
            hands.add(ids[index], cards.iter().copied()).unwrap();
        }
        (
            PlayPhase::new(
                propagated,
                1,
                GameMode::Tractor,
                hands,
                kitty,
                trump,
                ids[0],
                ids[0],
                vec![ids[0], ids[2]],
                vec![],
                vec![deck],
                vec![],
            )
            .unwrap(),
            ids,
        )
    }

    fn complete_one_deck_position_with_tied_root_prior() -> (PlayPhase, Vec<PlayerID>) {
        let ids: Vec<PlayerID> = (0..4).map(PlayerID).collect();
        let mut propagated = PropagatedState::default();
        propagated.players = ids
            .iter()
            .map(|id| Player::new(*id, format!("p{}", id.0)))
            .collect();
        propagated.num_decks = Some(1);
        let deck = Deck::default();
        let trump = Trump::NoTrump { number: None };
        let root_cards = [
            card(Suit::Clubs, Number::Two),
            card(Suit::Diamonds, Number::Two),
            card(Suit::Hearts, Number::Two),
            card(Suit::Spades, Number::Two),
            card(Suit::Clubs, Number::Three),
            card(Suit::Diamonds, Number::Three),
            card(Suit::Hearts, Number::Three),
            card(Suit::Spades, Number::Three),
            card(Suit::Clubs, Number::Four),
            card(Suit::Diamonds, Number::Four),
            card(Suit::Hearts, Number::Four),
            card(Suit::Spades, Number::Four),
            card(Suit::Clubs, Number::Six),
        ];
        let kitty = vec![Card::SmallJoker, Card::BigJoker];
        let reserved = root_cards
            .iter()
            .copied()
            .chain(kitty.iter().copied())
            .collect::<HashSet<_>>();
        let remaining = deck
            .cards()
            .filter(|card| !reserved.contains(card))
            .collect::<Vec<_>>();
        assert_eq!(remaining.len(), 39);

        let mut hands = Hands::new(ids.iter().copied());
        hands.set_trump(trump);
        hands.add(ids[0], root_cards).unwrap();
        for (index, cards) in remaining.chunks_exact(13).enumerate() {
            hands.add(ids[index + 1], cards.iter().copied()).unwrap();
        }
        (
            PlayPhase::new(
                propagated,
                1,
                GameMode::Tractor,
                hands,
                kitty,
                trump,
                ids[0],
                ids[0],
                vec![ids[0], ids[2]],
                vec![],
                vec![deck],
                vec![],
            )
            .unwrap(),
            ids,
        )
    }

    fn terminal_ruff_tradeoff_position(point_rich_pot: bool) -> (PlayPhase, Vec<PlayerID>) {
        let ids: Vec<PlayerID> = (0..4).map(PlayerID).collect();
        let mut propagated = PropagatedState::default();
        propagated.players = ids
            .iter()
            .map(|id| Player::new(*id, format!("p{}", id.0)))
            .collect();
        let trump = Trump::Standard {
            suit: Suit::Hearts,
            number: Number::Two,
        };
        let current_cards = if point_rich_pot {
            [
                card(Suit::Clubs, Number::King),
                card(Suit::Clubs, Number::King),
                card(Suit::Clubs, Number::Ten),
            ]
        } else {
            [
                card(Suit::Clubs, Number::Four),
                card(Suit::Clubs, Number::Ace),
                card(Suit::Clubs, Number::Three),
            ]
        };
        let partner_final = if point_rich_pot {
            card(Suit::Spades, Number::Four)
        } else {
            card(Suit::Spades, Number::Ten)
        };
        let mut hands = Hands::new(ids.iter().copied());
        hands.set_trump(trump);
        hands
            .add(
                ids[0],
                [
                    card(Suit::Diamonds, Number::Five),
                    current_cards[0],
                    partner_final,
                ],
            )
            .unwrap();
        hands
            .add(
                ids[1],
                [
                    card(Suit::Diamonds, Number::Ace),
                    current_cards[1],
                    card(Suit::Spades, Number::Ace),
                ],
            )
            .unwrap();
        hands
            .add(
                ids[2],
                [
                    card(Suit::Diamonds, Number::Ten),
                    card(Suit::Diamonds, Number::Three),
                    Card::BigJoker,
                ],
            )
            .unwrap();
        hands
            .add(
                ids[3],
                [
                    card(Suit::Diamonds, Number::Six),
                    current_cards[2],
                    card(Suit::Hearts, Number::Three),
                ],
            )
            .unwrap();
        let kitty = vec![
            card(Suit::Clubs, Number::Ten),
            card(Suit::Clubs, Number::Seven),
            card(Suit::Clubs, Number::Eight),
            card(Suit::Clubs, Number::Nine),
            card(Suit::Diamonds, Number::Seven),
            card(Suit::Diamonds, Number::Eight),
            card(Suit::Diamonds, Number::Nine),
            card(Suit::Spades, Number::Seven),
        ];
        let mut play = PlayPhase::new(
            propagated,
            2,
            GameMode::Tractor,
            hands,
            kitty,
            trump,
            ids[0],
            ids[0],
            vec![ids[0], ids[2]],
            vec![],
            vec![Deck::default(), Deck::default()],
            vec![],
        )
        .unwrap();
        // Seed the attackers with 15 points, just below the first 40-point
        // landlord-level boundary, and make player 1 the next leader.
        for (id, cards) in [
            (ids[0], vec![card(Suit::Diamonds, Number::Five)]),
            (ids[1], vec![card(Suit::Diamonds, Number::Ace)]),
            (ids[2], vec![card(Suit::Diamonds, Number::Ten)]),
            (ids[3], vec![card(Suit::Diamonds, Number::Six)]),
        ] {
            play.play_cards(id, &cards).unwrap();
        }
        play.finish_trick().unwrap();
        assert_eq!(play.calculate_points().0, 15);
        play.play_cards(ids[1], &[current_cards[1]]).unwrap();
        (play, ids)
    }

    fn keys(candidates: &[ScoredPlay]) -> Vec<Vec<char>> {
        candidates
            .iter()
            .map(|candidate| {
                let mut key = candidate
                    .cards
                    .iter()
                    .map(|card| card.as_char())
                    .collect::<Vec<_>>();
                key.sort_unstable();
                key
            })
            .collect()
    }

    #[test]
    fn root_candidate_order_is_canonical_and_deduplicated() {
        let club_three = card(Suit::Clubs, Number::Three);
        let heart_four = card(Suit::Hearts, Number::Four);
        let spade_five = card(Suit::Spades, Number::Five);
        let input = vec![
            ScoredPlay {
                cards: vec![heart_four],
                score: 1.0,
            },
            ScoredPlay {
                cards: vec![club_three],
                score: 1.0,
            },
            // Same physical multiset in another order and at a lower score.
            ScoredPlay {
                cards: vec![spade_five, club_three],
                score: 0.5,
            },
            ScoredPlay {
                cards: vec![club_three, spade_five],
                score: 0.25,
            },
        ];

        let mut reversed = input.clone();
        reversed.reverse();
        let first = canonicalize_ranked_candidates(input);
        let second = canonicalize_ranked_candidates(reversed);
        assert_eq!(keys(&first), keys(&second));
        assert_eq!(first.len(), 3, "equivalent card multisets are one action");
        assert!(first[0].score >= first[1].score);
        assert!(first[1].score >= first[2].score);
    }

    #[test]
    fn perfect_information_drops_a_known_failed_throw_in_favor_of_its_forced_unit() {
        let (play, ids) = joker_throw_position(true);
        let low_trump = card(Suit::Hearts, Number::Three);
        let failed_throw = vec![low_trump, Card::BigJoker];

        let mut probe = play.clone();
        probe.play_cards(ids[0], &failed_throw).unwrap();
        let played = probe.trick().played_cards().last().unwrap();
        assert_eq!(played.cards, vec![low_trump]);
        assert_eq!(played.bad_throw_cards, vec![Card::BigJoker]);

        let mut candidates = vec![
            ScoredPlay {
                cards: failed_throw.clone(),
                score: 100.0,
            },
            ScoredPlay {
                cards: vec![low_trump],
                score: 0.0,
            },
        ];
        remove_known_failed_throws(&play, ids[0], &mut candidates);

        assert_eq!(candidates.len(), 1);
        assert_eq!(candidates[0].cards, vec![low_trump]);

        let net_ranked = ranked_candidates(&play, ids[0], Policy::Net, EnochFeatures::empty());
        assert!(
            !net_ranked.iter().any(|candidate| {
                candidate.cards.len() == 2
                    && candidate.cards.contains(&low_trump)
                    && candidate.cards.contains(&Card::BigJoker)
            }),
            "the honest Net prior must apply the same unsafe-Joker lead filter"
        );
    }

    #[test]
    fn perfect_information_restores_an_actual_safe_throw_hidden_from_honest_ranking() {
        let (play, ids) = joker_throw_position(false);
        let mut safe_throw = vec![card(Suit::Hearts, Number::Three), Card::BigJoker];
        safe_throw.sort_by_key(|card| card.as_char());

        let honest = ranked_candidates(
            &play,
            ids[0],
            Policy::EnochHeuristic,
            EnochFeatures::empty(),
        );
        assert!(
            !honest.iter().any(|candidate| {
                let mut cards = candidate.cards.clone();
                cards.sort_by_key(|card| card.as_char());
                cards == safe_throw
            }),
            "honest ranking must reject a Joker throw that is not publicly proven safe"
        );

        let uncertain = ranked_candidates(
            &play,
            ids[0],
            Policy::EnochHeuristic,
            EnochFeatures::UNCERTAIN_THROWS,
        );
        assert!(
            uncertain.iter().any(|candidate| {
                let mut cards = candidate.cards.clone();
                cards.sort_by_key(|card| card.as_char());
                cards == safe_throw
            }),
            "the isolated uncertainty arm must expose the legal throw to search"
        );

        let mut perfect = ranked_candidates_perfect_information(
            &play,
            ids[0],
            Policy::EnochHeuristic,
            EnochFeatures::empty(),
        );
        remove_known_failed_throws(&play, ids[0], &mut perfect);
        assert!(
            perfect.iter().any(|candidate| {
                let mut cards = candidate.cards.clone();
                cards.sort_by_key(|card| card.as_char());
                cards == safe_throw
            }),
            "perfect-information ranking must retain a throw that succeeds in the true world"
        );

        let mut perfect_net = ranked_candidates_perfect_information(
            &play,
            ids[0],
            Policy::Net,
            EnochFeatures::empty(),
        );
        remove_known_failed_throws(&play, ids[0], &mut perfect_net);
        assert!(
            perfect_net.iter().any(|candidate| {
                let mut cards = candidate.cards.clone();
                cards.sort_by_key(|card| card.as_char());
                cards == safe_throw
            }),
            "the perfect-information Net prior must retain actual-safe Joker throws"
        );
    }

    #[test]
    fn adaptive_fraction_is_bounded_and_monotone_in_importance() {
        let minimum = 0.35;
        let routine = adaptive_fraction_from_signals(minimum, 0.0, 0.0, 0.0, 0.0);
        let uncertain = adaptive_fraction_from_signals(minimum, 1.0, 0.0, 0.0, 0.0);
        let critical = adaptive_fraction_from_signals(minimum, 1.0, 1.0, 1.0, 1.0);
        assert_eq!(routine, minimum);
        assert!(uncertain > routine);
        assert!((critical - 1.0).abs() < f64::EPSILON);
        assert!(routine >= minimum && critical <= 1.0);
    }

    #[test]
    fn progressive_work_budget_admits_actions_beyond_initial_top_k() {
        let control = SearchConfig {
            max_candidates: 4,
            max_worlds: 144,
            ..SearchConfig::default()
        };
        let candidate = SearchConfig {
            enoch_features: EnochFeatures::PROGRESSIVE_ADMISSION,
            ..control
        };
        assert_eq!(root_candidate_limit(&control, 20), 4);
        let pool = root_candidate_limit(&candidate, 20);
        assert!(pool > 4);
        assert!(pool <= 12);

        let fixed_work = control.max_candidates * control.max_worlds;
        let mut counts = vec![0usize; pool];
        let mut completed = 0usize;
        let mut work = 0usize;
        while completed < candidate.max_worlds && work < fixed_work {
            let active = progressive_active_count(control.max_candidates, pool, completed);
            let remaining = fixed_work - work;
            let round = active.min(remaining);
            let mut indices = (0..active).collect::<Vec<_>>();
            indices.sort_by_key(|&index| (counts[index], index));
            indices.truncate(round);
            for index in indices {
                counts[index] += 1;
                work += 1;
            }
            completed += 1;
        }
        assert_eq!(work, fixed_work, "candidate arm gets no extra work");
        assert!(counts.iter().all(|&count| count > 0));
    }

